"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[61724],{69060:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"ReviveGuiController","desc":"Revive menu, spectate bar and crew-down banner, driven only by the server\'s\\n`ReviveStateSync` (ReviveService decides everything). Binds three Studio-built\\nScreenGuis (`ReviveDimGui`, `ReviveGui`, `CrewDownGui`; ResetOnSpawn false).\\n\\nWhile the local player is down every other GUI is hidden (HudBlackout), the\\ncursor is free, and Roblox\'s Reset Character is off. At `RunOver` every\\nrevive GUI steps aside for the results screen (RunResultsController). Layout, copy and colors\\nfollow the approved prototype\\n(roblox-gui-prototypes/2026-10-20-revive-gui-prototype.html).\\nSee docs/systems/revive.md.","realm":["Client"],"source":{"line":17,"path":"src/StarterPlayer/StarterPlayerScripts/ReviveGuiController/init.client.luau"}}')}}]);